current.custom_css:
/* common*/
.m-topbar a[href*="pinterest"],
.m-topbar a[href*="twitter"],
.m-topbar a[href*="snapchat"],
.m-topbar a[href*="youtube"],
.m-topbar a[href*="tiktok"] {
  display: none;
}
.m-hero__content .m-hero__subtitle {
  margin-bottom: 20px;
}
.m-announcement-bar__content {
  font-weight: 500;
}
.m-product-card .m-price__sale .m-price-item--regular {
  font-size: var(--font-size-base);
}
.m-hero__bg .m-video__bg iframe,
.m-hero__bg .m-video__bg video {
  object-fit: cover;
  top: 0;
  width: 100%;
  height: 100%;
  left: 0;
}
.m-product-card__tags .m-product-card__tag-name {
  font-size: 12px;
  text-transform: none;
  height: 24px;
}
.m-richtext__subtitle,
.m-lookbook__subheading,
.m-hero__subtitle,
.m-collection-card--standard .m-collection-card__link,
.m-icon-box--small .m-icon-box__heading {
  font-size: calc(var(--font-h5-desktop) * 1px);
  font-weight: 500;
}
.m-custom-slideshow .m-slider__footer {
  gap: 0;
}
.m-custom-slideshow .m-slider__footer span + span {
  margin-left: 21px;
  color: rgba(var(--color-foreground), 0.3);
}
.m-custom-slideshow .m-slider__footer span + a {
  margin-left: 12px;
}
.m-product-card__info .m-price-item--regular {
  font-size: calc(var(--font-base-size, 16) * 1px);
}
.border-devider {
  border-bottom: 1px solid rgb(var(--color-border));
}
.m-section__header {
  --m-section-header-spacing-bottom: 40px;
}
.m-hero__content .m-hero__title {
  margin-bottom: 0;
}
/* common*/
/*footer*/
.m-footer .social-media-links {
  gap: 24px 44px;
  margin-top: 0;
  flex-wrap: wrap;
}
.m-footer .m-footer--block-newsletter .m-footer--block-title {
  font-size: calc(var(--font-h3-desktop) * 1px);
  font-weight: 400;
}
.m-footer .m-footer--middle .m-footer--block-title {
  margin-bottom: 20px;
}
.m-footer--block-newsletter-desc {
  margin-top: 33px;
}
.m-footer--block-newsletter .m-footer .m-footer--middle .m-footer--block-title {
  margin-bottom: 29px;
}
.m-footer--block-newsletter .m-accordion--item-content {
  display: flex;
  flex-direction: column;
}

.m-footer--block-newsletter .m-newsletter-form {
  order: -1;
}
/*footer*/

/*promotion*/
.m-icon-box--small .m-mixed-layout__inner .m\:column {
  position: relative;
}
.m-icon-box--small .m-mixed-layout__inner .m\:column:after {
  position: absolute;
  content: "";
  right: 0;
  top: 22px;
  bottom: 22px;
  width: 1px;
  height: calc(100% - 44px);
  background-color: rgb(var(--color-border));
}
.m-icon-box--small .m-mixed-layout__inner .m\:column:last-of-type:after {
  content: none;
}

.m-icon-box--small .m-icon-box__heading {
  line-height: 26px;
  margin-bottom: 6px;
}

/*promotion*/

@media (min-width: 768px) {
  .m-hero__title + .m-hero__text {
    margin-top: 24px;
  }
  .m-hero__title + .m-hero__btn {
    margin-top: 32px;
  }
}

@media (min-width: 1280px) {
  .m-footer .m-footer--middle .m-footer--block {
    padding: 90px 0;
  }
  .m-footer--bottom-inner {
    padding-bottom: 40px;
  }
}
@media (min-width: 768px) and (max-width: 1023px) {
.m-icon-box--small .m-mixed-layout__inner .m\:column:nth-child(even):after {
content: none;
}
}

@media (max-width: 767px) {
  /* common*/
  .m-richtext__subtitle,
  .m-lookbook__subheading,
  .m-hero__subtitle,
  .m-collection-card--standard .m-collection-card__link,
  .m-icon-box--small .m-icon-box__heading {
    font-size: calc(var(--font-h5-mobile) * 1px);
  }

  .m-section__header-with-button {
    text-align: center;
  }
  .m-hero__content .m-hero__title + .m-hero__content .m-hero__text {
    margin-top: 12px;
  }
  .m-hero__content .m-hero__subtitle {
    margin-bottom: 12px;
  }
  .m-hero__title + .m-hero__btn {
    margin-top: 24px;
  }
  .m-section-py {
    --section-padding-top-mobile: min(var(--section-padding-top), 48px);
    --section-padding-bottom-mobile: min(var(--section-padding-bottom), 48px);
  }
  /* common*/

  /* footer*/
  .m-footer .m-footer--block-newsletter .m-footer--block-title {
    font-size: calc(var(--font-h3-mobile) * 1px);
    font-weight: 400;
  }
  .m-footer .m-footer--middle .m-footer--block-title {
    margin-bottom: 9px;
  }
  .m-footer--block-newsletter-desc {
    margin-top: 16px;
  }

  /* footer*/
  .m-icon-box--small .m-icon-box__description {
    font-size: 14px;
  }
  .m-footer .m-footer--accordion .m-newsletter-form {
    margin-top: 0;
  }
}
